template <stdx::ct_string name,
          std::uint32_t   baseaddress,
          std::uint32_t   offset>
using otfdec_r4startaddr_v1_tt =
  groov::reg<name,
             std::uint32_t,
             baseaddress + offset,
             common::access::rw,
               groov::field<"reg4_start_addr", std::uint32_t, 31, 0>>;

